class Provider(object):
    @classmethod
    def provide(cls, kpi_name=None):
        """
        Get proper class based on class name.
        :param kpi_name:
        :return:
        """
        kpi_cls = getattr(SupportedKpi, kpi_name.lower())
        return kpi_cls
